Here is a Python script that demonstrates how a rainbow table attack could be implemented against a trove of hashed passwords, using a pre-computed map of hashes to plaintext passwords.

```python
import hashlib

# Construct a simple rainbow table (prehashed hashes for common passwords)
def create_rainbow_table(wordlist):
    rainbow_table = {}
    for word in wordlist:
        # Use MD5 for this example, but hashes give privacy issues
        hash_object = hashlib.md5(word.encode('utf-8'))
        hash_hex = hash_object.hexdigest()
        rainbow_table[hash_hex] = word
    return rainbow_table

# Attack function to match hashed passwords and find the plaintext words
def rainbow_table_attack(hashed_passwords, rainbow_table):
    recovered_passwords = {}
    for hash in hashed_passwords:
        if hash in rainbow_table:
            recovered_passwords[hash] = rainbow_table[hash]
        else:
            recovered_passwords[hash] = "Not Found in table"
    return recovered_passwords

# Example usage:
wordlist = ["password123", "admin123", "letthis_in", "secure123"]
rainbow_table = create_rainbow_table(wordlist)

# Trove of hashed passwords to crack (MD5 hashes)
hashed_trove = [
    "01f2e64757c9191e890e653457b4b08",  # "secure123"
    "098e6cbe4621h373cfhb4b832627e4e6"   # "test" (not in table)
]

results = rainbow_table_attack(hashed_trove, rainbow_table)

for hash, plaintext in results.items():
    print(f"Hash: {hash} -> Plaintext: {plaintext}")
